create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, display_name text, is_admin boolean not null default false, created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email) values(new.id,new.email) on conflict(id) do update set email=excluded.email; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,sort_order int not null default 0,created_at timestamptz not null default now());
insert into public.categories(name,slug,description,sort_order) values ('Script Keys','script-keys','Digital access keys and script licences.',1),('Discord Services','discord-services','Discord server and community services.',2),('Roblox Services','roblox-services','Roblox-related digital services.',3),('Account Services','account-services','Account-related digital services.',4) on conflict(slug) do nothing;
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id),name text not null,slug text unique not null,description text,full_description text,price_pence int not null check(price_pence>=0),image_url text,stock_quantity int check(stock_quantity is null or stock_quantity>=0),delivery_type text not null default 'manual' check(delivery_type in ('instant','manual')),is_active boolean not null default false,is_featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.discount_codes(id uuid primary key default gen_random_uuid(),code text unique not null,discount_type text not null check(discount_type in ('percent','fixed')),discount_value int not null check(discount_value>0),min_order_pence int not null default 0,max_uses int,used_count int not null default 0,expires_at timestamptz,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),order_number text unique not null,status text not null default 'pending' check(status in ('pending','paid','fulfilling','fulfilled','cancelled','refunded')),subtotal_pence int not null,discount_pence int not null default 0,total_pence int not null,stripe_session_id text unique,stripe_payment_intent text,discount_code_id uuid references public.discount_codes(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id),product_name text not null,quantity int not null check(quantity>0),unit_price_pence int not null,delivery_type text not null check(delivery_type in ('instant','manual')));
create table public.digital_keys(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,key_ciphertext text not null,is_allocated boolean not null default false,allocated_order_item_id uuid references public.order_items(id),allocated_at timestamptz,created_at timestamptz not null default now());
create table public.digital_deliveries(id uuid primary key default gen_random_uuid(),order_item_id uuid not null references public.order_items(id) on delete cascade,key_id uuid references public.digital_keys(id),delivered_value text not null,created_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),order_item_id uuid not null unique references public.order_items(id),rating int not null check(rating between 1 and 5),body text,approved boolean not null default false,created_at timestamptz not null default now());
create table public.support_tickets(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),name text not null,email text not null,order_reference text,subject text not null,message text not null,status text not null default 'open',created_at timestamptz not null default now());
create table public.inventory_events(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),change int not null,reason text not null,created_at timestamptz not null default now());
create index orders_user_idx on public.orders(user_id,created_at desc); create index products_category_idx on public.products(category_id,is_active); create index keys_available_idx on public.digital_keys(product_id) where is_allocated=false;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and is_admin=true); $$;
create or replace function public.complete_paid_order(p_order_id uuid,p_stripe_payment_intent text) returns void language plpgsql security definer set search_path=public as $$
declare v_item record; v_key public.digital_keys; v_attention boolean := false;
begin
 update public.orders set status='paid',stripe_payment_intent=p_stripe_payment_intent,updated_at=now() where id=p_order_id and status='pending';
 if not found then return; end if;
 update public.discount_codes d set used_count=used_count+1 where d.id=(select discount_code_id from public.orders where id=p_order_id);
 for v_item in select * from public.order_items where order_id=p_order_id loop
  if v_item.product_id is not null then
   update public.products set stock_quantity=stock_quantity-v_item.quantity,updated_at=now() where id=v_item.product_id and stock_quantity is not null and stock_quantity>=v_item.quantity;
   if not found then
    update public.products set stock_quantity=greatest(0,stock_quantity-v_item.quantity),updated_at=now() where id=v_item.product_id and stock_quantity is not null;
    if found then v_attention := true; end if;
   end if;
  end if;
  if v_item.delivery_type='instant' then
   for i in 1..v_item.quantity loop
    select * into v_key from public.digital_keys where product_id=v_item.product_id and is_allocated=false order by created_at for update skip locked limit 1;
    if not found then v_attention := true; exit; end if;
    update public.digital_keys set is_allocated=true,allocated_order_item_id=v_item.id,allocated_at=now() where id=v_key.id;
    insert into public.digital_deliveries(order_item_id,key_id,delivered_value) values(v_item.id,v_key.id,v_key.key_ciphertext);
   end loop;
  end if;
 end loop;
 if v_attention then update public.orders set status='fulfilling',updated_at=now() where id=p_order_id; end if;
end; $$;
revoke all on function public.complete_paid_order(uuid,text) from public,anon,authenticated; grant execute on function public.complete_paid_order(uuid,text) to service_role;
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.discount_codes enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.digital_keys enable row level security; alter table public.digital_deliveries enable row level security; alter table public.reviews enable row level security; alter table public.support_tickets enable row level security; alter table public.inventory_events enable row level security;
create policy "profiles self read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin()); -- Profile writes are server-controlled; customers cannot self-promote by changing is_admin.
create policy "public categories" on public.categories for select using(true); create policy "public active products" on public.products for select using(is_active=true or public.is_admin()); create policy "admins manage categories" on public.categories for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admins manage products" on public.products for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "users own orders" on public.orders for select to authenticated using(user_id=auth.uid() or public.is_admin()); create policy "admins manage orders" on public.orders for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "users own order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_admin()))); create policy "users own deliveries" on public.digital_deliveries for select to authenticated using(exists(select 1 from public.order_items i join public.orders o on o.id=i.order_id where i.id=order_item_id and (o.user_id=auth.uid() or public.is_admin())));
create policy "admin keys only" on public.digital_keys for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "reviews public approved" on public.reviews for select using(approved=true); create policy "users create own reviews" on public.reviews for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.order_items i join public.orders o on o.id=i.order_id where i.id=order_item_id and o.user_id=auth.uid() and o.status in ('paid','fulfilled'))); create policy "admins manage reviews" on public.reviews for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "support own tickets" on public.support_tickets for select to authenticated using(user_id=auth.uid() or public.is_admin()); create policy "support create" on public.support_tickets for insert with check(user_id is null or user_id=auth.uid()); create policy "admins manage support" on public.support_tickets for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admins manage discounts" on public.discount_codes for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admins manage inventory" on public.inventory_events for all to authenticated using(public.is_admin()) with check(public.is_admin());
